[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Biomedical Research Landscape 2024–2026</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a365d;
    --primary-light: #2b5b9e;
    --accent: #2563eb;
    --accent2: #0891b2;
    --success: #059669;
    --warning: #d97706;
    --danger: #dc2626;
    --bg: #f8fafc;
    --surface: #ffffff;
    --border: #e2e8f0;
    --text: #1e293b;
    --text-muted: #64748b;
    --text-light: #94a3b8;
    --font: 'Segoe UI', system-ui, -apple-system, sans-serif;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: var(--font);
    background: var(--bg);
    color: var(--text);
    line-height: 1.65;
    font-size: 15px;
  }

  /* Cover Page */
  .cover {
    background: linear-gradient(135deg, #0f2044 0%, #1a365d 40%, #1e4d8c 70%, #2563eb 100%);
    color: white;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    padding: 60px 40px;
    position: relative;
    overflow: hidden;
  }

  .cover::before {
    content: '';
    position: absolute;
    top: -50%; left: -50%;
    width: 200%; height: 200%;
    background: radial-gradient(ellipse at 70% 30%, rgba(37,99,235,0.25) 0%, transparent 60%),
                radial-gradient(ellipse at 20% 80%, rgba(8,145,178,0.2) 0%, transparent 50%);
  }

  .cover-content { position: relative; z-index: 1; max-width: 820px; }

  .cover-tag {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.3);
    border-radius: 20px;
    padding: 6px 18px;
    font-size: 12px;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 28px;
    backdrop-filter: blur(4px);
  }

  .cover h1 {
    font-size: 42px;
    font-weight: 700;
    line-height: 1.2;
    margin-bottom: 20px;
    letter-spacing: -0.5px;
  }

  .cover h1 span { color: #93c5fd; }

  .cover-subtitle {
    font-size: 18px;
    opacity: 0.85;
    max-width: 620px;
    margin: 0 auto 40px;
    line-height: 1.6;
  }

  .cover-meta {
    display: flex;
    gap: 40px;
    justify-content: center;
    flex-wrap: wrap;
    margin-top: 50px;
    padding-top: 40px;
    border-top: 1px solid rgba(255,255,255,0.2);
  }

  .cover-meta-item { text-align: center; }
  .cover-meta-value {
    font-size: 28px;
    font-weight: 700;
    color: #93c5fd;
    display: block;
  }
  .cover-meta-label {
    font-size: 12px;
    opacity: 0.7;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-top: 4px;
  }

  .cover-date {
    margin-top: 48px;
    font-size: 13px;
    opacity: 0.6;
  }

  /* Layout */
  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 32px;
  }

  /* TOC */
  .toc-section {
    background: var(--surface);
    border-bottom: 1px solid var(--border);
    padding: 60px 0;
  }

  .toc-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 16px;
    margin-top: 32px;
  }

  .toc-item {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 16px 20px;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: var(--bg);
    transition: all 0.2s;
    text-decoration: none;
    color: var(--text);
  }

  .toc-item:hover {
    border-color: var(--accent);
    background: #eff6ff;
    box-shadow: 0 2px 8px rgba(37,99,235,0.1);
  }

  .toc-num {
    width: 36px; height: 36px;
    background: var(--primary);
    color: white;
    border-radius: 8px;
    display: flex; align-items: center; justify-content: center;
    font-size: 14px; font-weight: 700;
    flex-shrink: 0;
  }

  .toc-title { font-size: 14px; font-weight: 600; line-height: 1.3; }
  .toc-sub { font-size: 12px; color: var(--text-muted); margin-top: 2px; }

  /* Section layout */
  .report-section {
    padding: 72px 0;
    border-bottom: 1px solid var(--border);
  }

  .report-section:nth-child(even) { background: var(--surface); }
  .report-section:nth-child(odd) { background: var(--bg); }

  /* Section headers */
  .section-header {
    margin-bottom: 40px;
  }

  .section-tag {
    display: inline-block;
    background: #dbeafe;
    color: var(--accent);
    border-radius: 4px;
    padding: 3px 10px;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    margin-bottom: 10px;
  }

  .section-header h2 {
    font-size: 30px;
    font-weight: 700;
    color: var(--primary);
    line-height: 1.2;
    margin-bottom: 12px;
  }

  .section-header p {
    color: var(--text-muted);
    max-width: 680px;
    font-size: 15px;
  }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
    margin-bottom: 48px;
  }

  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    position: relative;
    overflow: hidden;
  }

  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }

  .kpi-card.blue::before { background: var(--accent); }
  .kpi-card.teal::before { background: var(--accent2); }
  .kpi-card.green::before { background: var(--success); }
  .kpi-card.amber::before { background: var(--warning); }
  .kpi-card.red::before { background: var(--danger); }

  .kpi-icon {
    width: 40px; height: 40px;
    border-radius: 10px;
    display: flex; align-items: center; justify-content: center;
    font-size: 20px;
    margin-bottom: 16px;
  }

  .kpi-card.blue .kpi-icon { background: #dbeafe; }
  .kpi-card.teal .kpi-icon { background: #cffafe; }
  .kpi-card.green .kpi-icon { background: #d1fae5; }
  .kpi-card.amber .kpi-icon { background: #fef3c7; }
  .kpi-card.red .kpi-icon { background: #fee2e2; }

  .kpi-value {
    font-size: 32px;
    font-weight: 800;
    color: var(--primary);
    line-height: 1;
    margin-bottom: 6px;
  }

  .kpi-label {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  .kpi-sub {
    font-size: 12px;
    color: var(--text-light);
    margin-top: 8px;
  }

  /* Charts */
  .chart-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(460px, 1fr));
    gap: 28px;
    margin-bottom: 32px;
  }

  .chart-grid-3 {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 24px;
    margin-bottom: 32px;
  }

  .chart-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
  }

  .chart-title {
    font-size: 15px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 4px;
  }

  .chart-subtitle {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 20px;
  }

  .chart-wrap {
    position: relative;
  }

  /* Tables */
  .table-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    overflow: hidden;
    margin-bottom: 28px;
  }

  .table-header {
    padding: 18px 24px;
    border-bottom: 1px solid var(--border);
    background: #f8fafc;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .table-header-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--primary);
  }

  .table-header-sub {
    font-size: 12px;
    color: var(--text-muted);
  }

  .data-table {
    width: 100%;
    border-collapse: collapse;
  }

  .data-table th {
    background: #f1f5f9;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    padding: 12px 20px;
    text-align: left;
    border-bottom: 1px solid var(--border);
  }

  .data-table td {
    padding: 12px 20px;
    font-size: 13.5px;
    border-bottom: 1px solid #f1f5f9;
    color: var(--text);
  }

  .data-table tr:last-child td { border-bottom: none; }
  .data-table tr:hover td { background: #f8fafc; }

  .badge {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
  }

  .badge-blue { background: #dbeafe; color: #1d4ed8; }
  .badge-green { background: #d1fae5; color: #065f46; }
  .badge-amber { background: #fef3c7; color: #92400e; }
  .badge-red { background: #fee2e2; color: #991b1b; }
  .badge-gray { background: #f1f5f9; color: #475569; }

  .bar-inline {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .bar-fill {
    height: 6px;
    background: var(--accent);
    border-radius: 3px;
    flex-shrink: 0;
  }

  .bar-fill.teal { background: var(--accent2); }
  .bar-fill.green { background: var(--success); }

  /* Insight callouts */
  .insight-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
    margin-top: 32px;
  }

  .insight-card {
    border-radius: 10px;
    padding: 20px 22px;
    border-left: 4px solid;
  }

  .insight-card.info {
    background: #eff6ff;
    border-color: var(--accent);
  }

  .insight-card.success {
    background: #f0fdf4;
    border-color: var(--success);
  }

  .insight-card.warning {
    background: #fffbeb;
    border-color: var(--warning);
  }

  .insight-card.neutral {
    background: #f8fafc;
    border-color: var(--text-light);
  }

  .insight-label {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1px;
    text-transform: uppercase;
    margin-bottom: 6px;
    opacity: 0.7;
  }

  .insight-card.info .insight-label { color: var(--accent); }
  .insight-card.success .insight-label { color: var(--success); }
  .insight-card.warning .insight-label { color: var(--warning); }

  .insight-title { font-size: 14px; font-weight: 700; margin-bottom: 6px; }
  .insight-body { font-size: 13px; line-height: 1.6; color: var(--text-muted); }

  /* Annotation box */
  .annotation {
    background: #fef3c7;
    border: 1px solid #fcd34d;
    border-radius: 8px;
    padding: 14px 18px;
    font-size: 13px;
    color: #78350f;
    margin-bottom: 28px;
    display: flex;
    gap: 10px;
    align-items: flex-start;
  }

  .annotation-icon { font-size: 16px; flex-shrink: 0; margin-top: 1px; }

  /* Key Takeaways */
  .takeaway-list {
    display: grid;
    gap: 20px;
    margin-top: 32px;
  }

  .takeaway-item {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px 28px;
    display: grid;
    grid-template-columns: 48px 1fr;
    gap: 20px;
    align-items: start;
  }

  .takeaway-num {
    width: 48px; height: 48px;
    background: var(--primary);
    color: white;
    border-radius: 12px;
    display: flex; align-items: center; justify-content: center;
    font-size: 20px; font-weight: 800;
  }

  .takeaway-title {
    font-size: 16px;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 8px;
  }

  .takeaway-body { font-size: 14px; color: var(--text-muted); line-height: 1.7; }

  .takeaway-implication {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid var(--border);
    font-size: 13px;
    color: var(--accent);
    font-weight: 600;
  }

  .takeaway-implication::before { content: "→ Strategic Implication: "; }

  /* Footer */
  .report-footer {
    background: var(--primary);
    color: rgba(255,255,255,0.7);
    padding: 40px 0;
    text-align: center;
    font-size: 13px;
  }

  .report-footer strong { color: white; }

  /* Responsive */
  @media (max-width: 768px) {
    .cover h1 { font-size: 28px; }
    .chart-grid { grid-template-columns: 1fr; }
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .container { padding: 0 16px; }
  }

  /* Print */
  @media print {
    .cover { min-height: auto; page-break-after: always; }
    .report-section { page-break-inside: avoid; }
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: var(--bg); }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }
</style>
